use std::fs

fn is_leap(y: int) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn month_len(y: int, m: int) -> int {
    if m == 2 {
        if is_leap(y) { return 29 }
        return 28
    }
    if m == 4 || m == 6 || m == 9 || m == 11 { return 30 }
    31
}

// returns day number, or -1 when invalid
fn parse_date(tok: string) -> int {
    let mut nums: Vec<int> = []
    let mut lens: Vec<int> = []
    let mut cur = 0
    let mut n = 0
    let mut parts = 0
    for c in tok.chars() {
        if c == '-' {
            nums.push(cur)
            lens.push(n)
            cur = 0
            n = 0
            parts += 1
        } else if c >= '0' && c <= '9' {
            cur = cur * 10 + (c as int - '0' as int)
            n += 1
        } else {
            return -1
        }
    }
    nums.push(cur)
    lens.push(n)
    parts += 1
    if parts != 3 { return -1 }
    if lens[0] != 4 || lens[1] != 2 || lens[2] != 2 { return -1 }
    let y = nums[0]
    let m = nums[1]
    let d = nums[2]
    if y < 1900 || y > 2100 { return -1 }
    if m < 1 || m > 12 { return -1 }
    if d < 1 || d > month_len(y, m) { return -1 }
    let p = y - 1
    let mut total = 365 * p + p / 4 - p / 100 + p / 400
    let mut i = 1
    while i < m {
        total += month_len(y, i)
        i += 1
    }
    total + d
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let names = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
    for line in text.lines() {
        let toks: Vec<string> = line.split_whitespace().collect()
        if toks.len() == 0 { continue }
        if toks.len() != 2 {
            println("invalid")
            continue
        }
        let a = parse_date(toks[0])
        let b = parse_date(toks[1])
        if a < 0 || b < 0 {
            println("invalid")
            continue
        }
        let lo = if a < b { a } else { b }
        let diff = if a < b { b - a } else { a - b }
        let w = ((lo - 1) % 7) as usize
        println("${diff} ${names[w]}")
    }
}

